const{contextBridge:i,ipcRenderer:r}=require("electron");i.exposeInMainWorld("desktop",{openFile(){return r.invoke("dialog:openFile")},saveFile(e){return!e||typeof e.content!="string"?Promise.reject(new Error("saveFile: content must be a string")):r.invoke("dialog:saveFile",{content:e.content,defaultPath:typeof e.defaultPath=="string"?e.defaultPath:void 0})},exportPdf(){return r.invoke("dialog:exportPdf")},onOpenFile(e){const n=(o,t)=>e(t);return r.on("menu:openFile",n),()=>r.removeListener("menu:openFile",n)},onSaveFile(e){const n=(o,t)=>e(t);return r.on("menu:saveFile",n),()=>r.removeListener("menu:saveFile",n)},onSaveFileAs(e){const n=(o,t)=>e(t);return r.on("menu:saveFileAs",n),()=>r.removeListener("menu:saveFileAs",n)},onFileOpened(e){const n=(o,t)=>e(t);return r.on("file:opened",n),()=>r.removeListener("file:opened",n)},isDesktop:!0});
